import logging
import os
import re
import time

from .exceptions import (BuildDeletionFailed, BuildNotFoundInTemp,
                         FileIsBeingUploaded, UploadFailed)
from .swm_command import SwmCommand

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ImportableBuild:

    def __init__(self, version_id, mo_type, release=None, file_name=None, local_path=None, target_path=None):
        self.version_id = version_id  # e.g. SBTS00_ENB_9999_201215_000009
        self.mo_type = mo_type
        self.release = release
        self.file_name = file_name  # e.g. SBTS00_ENB_9999_201215_000009.zip
        self.local_path = local_path
        self.target_path = target_path

    @classmethod
    def from_file_path(cls, local_path, target_dir, mo_type, version_id=None, release=None):
        """
        :param string local_path: e.g. '/home/ute/FL00_FSM3_9999_160511_030083.zip'
        :param string target_dir: e.g. '/d/oss/global/swmanager/swm_temp/'
        :param string mo_type: e.g. 'MRBTS'
        :param version_id: e.g. 'FL00_FSM3_9999_160511_030083'
        :param (string|list(string)) release: software package argument. A string or a list can be used,
            e.g., 'Tl17', or '['TL16', 'TL16A', 'TL17']
        :return: build
        :rtype: ImportableBuild
        """
        file_name = os.path.basename(local_path)  # e.g. FL00_FSM3_9999_160511_030083.zip
        version_id = version_id
        target_path = target_dir + file_name
        return cls(version_id, mo_type, release=release,
                   file_name=file_name, local_path=local_path, target_path=target_path)


class SwmImporter:
    NETACT_TEMP_STORAGE_PATH = '/d/oss/global/swmanager/swm_temp/'

    def __init__(self, was_node):
        self.was_node = was_node

    def import_build(self, build_or_file_path, mo_type='MRBTS', version_id=None, release=None,
                     clean_temp_storage=False, ccr=None):
        """
        Perform a basic import of a software package to NetAct:
         - check if build is already imported (if so - no need to import it again)
         - if not, try to import build from temporary storage, i.e., without uploading the file
         - if the previous step fails - upload build to NetAct temporary storage and try to import it again

        **NOTE: This KW uses a command available in swmCLI.sh since NetAct 20 SP2011 **

        The command requires package name and compatible managed objects type arguments.
        If the XML description file is added to the software package, the SW Import Form dialog is
        automatically filled with the information taken from this file. Compatible releases and version ID
        can be provided optionally. In such case user input overwrites data from the XML description file.

        Package ``versionID`` is displayed in the output when the import is completed.

        :param string build_or_file_path: name of a build in NetAct software temp storage
            (``/d/oss/global/swmanager/swm_temp/``), e.g., SBTS22R1_ENB_0000_000089_000000.zip,
            or path to local SW package, e.g., /home/ute/SBTS22R1_ENB_0000_000089_000000.zip
        :param string mo_type: managed object type, 'MRBTS' by default
        :param string version_id: software package argument. Only one value in ``versionID`` can be used,
            e.g., TL16A_ENB_0000_000351_000000
        and multiple values
        :param (string|list(string)) release: software package argument. A string or a list can be used,
            e.g., 'Tl17, or '['TL16', 'TL16A', 'TL17']
        :param bool clean_temp_storage: specifies if SW package has to be deleted from NetAct software
            temporary storage after import (applies only to SW packages uploaded from a local machine)
        :param bool ccr: enables/disables distribution to Central Container Registry (CCR)
            if supported by ``mo-type``. If not specified, distribution to CCR is executed only for packages
            imported for CNF ``mo-type``
        """
        build = ImportableBuild.from_file_path(build_or_file_path, self.NETACT_TEMP_STORAGE_PATH,
                                               mo_type, version_id, release)

        version_id = version_id or re.match(r'^.+\d+', build.file_name).group()
        with self.was_node as ssh:
            if self.is_imported(version_id, mo_type=build.mo_type):
                logger.info(f'Build {version_id} is already imported')
                return
            elif ssh.file_exists(build.target_path):
                self._check_if_build_is_being_uploaded(build.target_path)
                self._import_build_from_netact_temp_storage(build, ccr=ccr)
            else:
                logger.info('Failed to import build from NetAct software temp storage')
                self._upload_build(build)
                self._import_build_from_netact_temp_storage(build,
                                                            clean_temp_storage=clean_temp_storage,
                                                            ccr=ccr)

    def _import_build_from_netact_temp_storage(self, build, clean_temp_storage=False, ccr=None):
        options = {
            '--operation': 'import',
            '--file': build.file_name,
            '--mo-type': build.mo_type,
            '--args': {'versionID': build.version_id, 'release': build.release},
        }

        # a workaround for `--ccr` option that is provided in a non-standard way:
        # `--ccr=false` instead of `--ccr false` etc.
        arguments = [f"--ccr={'true' if ccr else 'false'}"] if ccr is not None else []
        command = SwmCommand(options=options, arguments=arguments)

        with self.was_node as ssh:
            try:
                output = ssh.execute_command(command.text).stdout
            finally:
                if clean_temp_storage:
                    ssh.execute_command(f'rm -f {build.target_path}')

        if 'not exist' in output:
            # full output: u'Error SWMT0100: Package file does not exist in temporary storage'
            raise BuildNotFoundInTemp(output)

        logger.debug(output)
        return output

    def _upload_build(self, build):
        # type: (ImportableBuild) -> None
        logger.info(f'Uploading {build.local_path} to NetAct')
        try:
            with self.was_node as ssh:
                ssh.put_file(build.local_path, build.target_path)
            logger.info('Upload finished')
        except IOError:
            raise UploadFailed('Some other process interrupted the upload.')

    def _check_if_build_is_being_uploaded(self, target_path, recheck_interval=1):
        with self.was_node as ssh:
            initial_file_size = ssh.get_file_size(target_path)
            time.sleep(recheck_interval)
            new_file_size = ssh.get_file_size(target_path)
            if initial_file_size != new_file_size:
                raise FileIsBeingUploaded(f'{target_path} is being uploaded to NetAct by some other process.')

    def get_list_of_imported_builds(self, mo_type='MRBTS'):
        """
        Get list of imported software archives of a specified type

        **NOTE: This KW uses a command available in swmCLI.sh since NetAct 20 SP2011 **

        :param string mo_type: managed object type, 'MRBTS' by default
        :return: names of imported builds
        :rtype: list(string)
        """
        command = SwmCommand(
            options={
                '--operation': 'list-packages',
                '--mo-type': mo_type
            }
        )

        with self.was_node as ssh:
            ssh_output = ssh.execute_command(command.text, ignore_rc=False)
            output = ssh_output.stdout

        imported_builds = output.strip().split(',')
        logger.info('Imported builds:\n - ' + '\n - '.join(imported_builds))

        return imported_builds

    def is_imported(self, version_id, mo_type='MRBTS'):
        """
        Checks if build is imported into NetAct.

        **NOTE: This KW uses a command available in swmCLI.sh since NetAct 20 SP2011 **

        :param string version_id: e.g FL00_FSM3_9999_160511_030083
        :param string mo_type: managed object type, 'MRBTS' by default
        :return: import status
        :rtype: bool
        """
        imported_builds = self.get_list_of_imported_builds(mo_type)
        return version_id in imported_builds

    def delete_build(self, version_ids, mo_type='MRBTS'):
        """
        Delete software packages for specified MO type and software package versions

        **NOTE: This KW uses a command available in swmCLI.sh since NetAct 20 SP2011 **

        :param (string|list(string)) version_ids: e.g 'FL00_FSM3_9999_160511_030083', or a list of IDs,
            e.g., ['MUXX7000', 'MUXX80F3']
        :param string mo_type: managed object type, e.g., 'MRBTS', 'MSS', 'OMGW'
        """
        command = SwmCommand(
            options={
                '--operation': 'delete-packages',
                '--mo-type': mo_type,
                '--sw-versions': version_ids
            }
        )

        with self.was_node as ssh:
            ssh_output = ssh.execute_command(command.text, ignore_rc=False)
            output = ssh_output.stdout

        logger.debug(output)

        if "couldn't have been deleted" in output:
            raise BuildDeletionFailed(output)
